async function gatherMarketplaces(searchId:string,expanded=false){
 const queue=connection.apifyShared||!expanded?['automotive']:['automotive','retail','facebook'];
 for(let batch=0;batch<4&&queue.length;batch++){
 const provider=queue.shift()!;
 if(stopGathering.current||queuedChat.current)break;
 const call=async(action:string)=>{const r=await fetch('/api/marketplaces',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,searchId,provider,advance:true})});const data:{done:boolean;hasMore?:boolean;error?:string}=await r.json();if(!r.ok)throw Error(data.error);return data;};
 try{setPriceProgress(provider==='facebook'?'Searching Facebook Marketplace local regions…':provider==='retail'?'Searching Carvana inventory…':'Searching connected marketplaces…');let result=await call('start');
  for(let poll=0;poll<60&&!result.done&&!stopGathering.current&&!queuedChat.current;poll++){
   await new Promise(resolve=>setTimeout(resolve,5000));if(queuedChat.current)break;result=await call('poll');
   const response=await fetch('/api/workspace');const data:WorkspaceSnapshot=await response.json();if(!response.ok)throw Error(data.error);if(data.workspace.searchId!==searchId)return;accept(data);
  }
  if(expanded&&result.done&&result.hasMore&&!connection.apifyShared)queue.push(provider);
  if(!result.done&&!queuedChat.current)toast.info('Marketplace search is still running. Use Check more marketplaces to retrieve it.');
 }catch(e){const message=e instanceof Error?e.message:'Marketplace search paused. Your existing cars remain available.';setMarketplaceNotice(message);toast.info(message);if(/allowance|credit|billing cycle/i.test(message))break;}
 finally{setPriceProgress('');}
 }
}
